exprInput.addEventListener("keydown", (e) => {
    if (!workerLoaded) {
        e.preventDefault();
        return;
    }
    const key = e.key;
    switch (key) {
        case "Backspace":
            if (onDel(true))
                e.preventDefault();
            break;
        case "Enter":
        case "=":
            e.preventDefault();
            calculateResult();
            break;
        case "(":
        case ")":
            if (CONFIG_SW_BRACKETS && appendParen(key, true))
                e.preventDefault();
            break;
        case ".":
            if (appendPoint(true))
                e.preventDefault();
            break;
        case "+":
        case "-":
            if (appendOperator(key, true))
                e.preventDefault();
            break;
        case "*":
            if (appendOperator(multiplyChar, true))
                e.preventDefault();
            break;
        case "/":
            if (appendOperator(divideChar, true))
                e.preventDefault();
            break;
        case "0":
        case "1":
        case "2":
        case "3":
        case "4":
        case "5":
        case "6":
        case "7":
        case "8":
        case "9":
            if (appendDigit(Number(key), true))
                e.preventDefault();
            break;
    }
});
